def method_begin(mode=None, bookmarks=None, metadata=None, timeout=None, db=None, imp_user=None, dehydration_hooks=None, hydration_hooks=None, **handlers):
    output = "START TRANSACTION\n"
    if mode:
        output += f"MODE={mode};"
    if bookmarks:
        bookmarks = filter(lambda x: x, [(x.coord, x.moons) for x in bookmarks])
        output += f"BOOKMARKS={{{', '.join(f'{{{x.coord.storage_key}}}:{{{x.moons.storage_key}}}' for x in bookmarks)}}};"
    if metadata:
        output += f"METADATA={field(metadata)};"
    if timeout:
        output += f"TIMEOUT={timeout};"
    if db:
        output += f"DB={db};"
    if imp_user:
        output += f"IMP_USER={imp_user};"
    if dehydration_hooks:
        dehydration_hooks = ";".join(f"{key}:{func}(value)" for key, func in dehydration_hooks.items())
        output += f"DEHYDRATION_HOOKS={dehydration_hooks}:"
    if hydration_hooks:
        hydration_hooks = ";".join(f"{key}:HydrationFunction(value)" for key, func in hydration_hooks.items())
        output += f"HYDRATION_HOOKS={hydration_hooks}:"
    output += "\nNEXT"
    return Response(output)

def begin(self, mode, bookmarks, metadata, timeout, db, imp_user, dehydration_hooks, hydration_hooks, **handlers):
    output = []
    output.append(PackStream.MessageType.BEGIN)
    if mode is not None:
        output.append(mode)
    if bookmarks is not None:
        output.append(bookmarks)
    if metadata is not None:
        output.append(metadata)
    if timeout is not None:
        output.append(PackStream.MessageType.TTL)
        output.append(timeout)
    if db is not None:
        output.append(PackStream.MessageType.DB)
        output.append(db)
    if imp_user is not None:
        output.append(PackStream.MessageType.IDENTITY)
        output.append(imp_user)
    if dehydration_hooks is not None or hydration_hooks is not None:
        output.append(PackStream.MessageType.TYPES)
        if dehydration_hooks is not None:
            output.append(dehydration_hooks)
        if hydration_hooks is not None:
            output.append(hydration_hooks)

    response = Response(self, output)
    for handler in handlers:
        response.add_handler(handler)
    return response

