def integral(bins, edges):
    if type(bins) != list or type(edges) != list:
        raise TypeError("Bins and edges must be lists")

    if len(bins) != len(edges):
        raise ValueError("Bins and edges must have the same length")

    if len(bins) < 2:
        raise ValueError("Must provide at least two bins")

    total_area = 0.0
    for i in range(len(bins) - 1):
        base = edges[i]
        height = bins[i]
        width = edges[i + 1] - edges[i]
        area = width * height
        total_area += area

    return total_area

def integral(bins, edges):
    if len(bins) != len(edges) - 1:
        raise ValueError("len(bins) must be equal to len(edges) - 1")
    scale = 0.0
    for i in range(len(bins)):
        width = edges[i+1] - edges[i]
        height = sum(bins[i:i+1])
        scale += width * height / 2
    return scale

