def format(self, sql, params):
    formatted_sql = sql
    formatted_params = {}
    if isinstance(params, dict):
        for key, val in params.items():
            if isinstance(key, str):
                formatted_sql = formatted_sql.replace(key, ':{}'.format(key))
            else:
                formatted_sql = formatted_sql.replace('{0}'.format(key), ':{}'.format(key))
                formatted_params[key] = val
    elif isinstance(params, list):
        for idx, val in enumerate(params):
            formatted_sql = formatted_sql.replace('{0}'.format(idx), ':{}'.format(idx))
            formatted_params[idx] = val
    else:
        raise TypeError("Unsupported params type: {}".format(type(params)))
    return formatted_sql, formatted_params

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if self.in_style is None:
        raise ValueError("Method requires self.in_style to be set")
    if self.in_style.start_symbol not in sql:
        return (sql, params)
    if isinstance(params, Mapping):
        return (self.format_mapping(sql, params), self.format_mapping(params))
    return (self.format_sequence(sql, params), self.format_sequence(params))

