def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, And) and isinstance(arg.operands[0], EqualTo) and isinstance(arg.operands[1], Or):
            if arg.operands[0].operands[0] == arg.operands[0].operands[1]:
                new_args.append(arg.operands[0].operands[0])
        elif isinstance(arg, And) and isinstance(arg.operands[0], NotEqualTo) and isinstance(arg.operands[1], And):
            if arg.operands[0].operands[0] == arg.operands[0].operands[1]:
                new_args.append(arg.operands[0].operands[0] & arg.operands[1])
        elif isinstance(arg, Or) and isinstance(arg.operands[0], And) and isinstance(arg.operands[1], EqualTo):
            if arg.operands[1].operands[0] == arg.operands[1].operands[1]:
                new_args.append(arg.operands[1].operands[0])
        elif isinstance(arg, Or) and isinstance(arg.operands[0], And) and isinstance(arg.operands[1], NotEqualTo):
            if arg.operands[1].operands[0] == arg.operands[1].operands[1]:
                new_args.append(arg.operands[1].operands[0] | arg.operands[1])
        else:
            new_args.append(arg)
    return new_args

